const cfg = $json;
if (!cfg.locationId) throw new Error('Missing locationId');
if (!cfg.apiKey) throw new Error('Missing apiKey in Config node');

const baseUrl = (cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const locationId = cfg.locationId;
const dryRun = !!cfg.dryRun;

const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (typeof this !== 'undefined' && this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP not available in Code node runtime.');
}

async function apiRequest(method, path, body) {
  const options = { method, url: `${baseUrl}${path}`, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    const status = err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500;
    const data = err?.response?.body || err?.message || err;
    return { ok: false, status, data };
  }
}

function normalizeType(value) {
  const v = String(value || '').toUpperCase();
  if (!v) return '';
  if (['SINGLE_OPTIONS', 'DROPDOWN', 'SINGLE_SELECT', 'SELECT', 'OPTION'].some((x) => v.includes(x))) return 'DROPDOWN_SINGLE';
  if (['DATE_TIME', 'DATETIME', 'DATE'].some((x) => v.includes(x))) return 'DATE';
  if (['NUM', 'INT', 'FLOAT', 'DECIMAL', 'NUMBER'].some((x) => v.includes(x))) return 'NUMBER';
  if (['TEXT', 'STRING', 'LONG_TEXT', 'LARGE_TEXT'].some((x) => v.includes(x))) return 'TEXT';
  return v;
}

function extractFieldType(field) {
  return normalizeType(field?.dataType || field?.fieldType || field?.type || field?.valueType);
}

function extractFieldName(field) {
  return field?.name || field?.label || field?.fieldName || '';
}

function getCustomFieldsArray(data) {
  if (Array.isArray(data?.customFields)) return data.customFields;
  if (Array.isArray(data?.data?.customFields)) return data.data.customFields;
  if (Array.isArray(data?.data)) return data.data;
  if (Array.isArray(data)) return data;
  return [];
}

const requiredFields = [
  { name: 'UTM Source First', requiredType: 'TEXT' },
  { name: 'UTM Medium First', requiredType: 'TEXT' },
  { name: 'UTM Campaign First', requiredType: 'TEXT' },
  { name: 'UTM Content First', requiredType: 'TEXT' },
  { name: 'UTM Term First', requiredType: 'TEXT' },
  { name: 'UTM Source Last', requiredType: 'TEXT' },
  { name: 'UTM Medium Last', requiredType: 'TEXT' },
  { name: 'UTM Campaign Last', requiredType: 'TEXT' },
  { name: 'UTM Content Last', requiredType: 'TEXT' },
  { name: 'UTM Term Last', requiredType: 'TEXT' },
  { name: 'UTM Landing Page First', requiredType: 'TEXT' },
  { name: 'UTM Landing Page Last', requiredType: 'TEXT' },
  { name: 'LT Last Routing Reason', requiredType: 'TEXT' },
  { name: 'LT Last Routing Channel', requiredType: 'TEXT' },
  { name: 'LT Last Routed At', requiredType: 'DATE' },
  { name: 'LT Route Lock Until', requiredType: 'DATE' },
  { name: 'LT Routing Priority', requiredType: 'NUMBER' },
  { name: 'LT Last Event Fingerprint', requiredType: 'TEXT' },
  { name: 'LT Last Event At', requiredType: 'DATE' },
];

const fieldsRes = await apiRequest.call(this, 'GET', `/locations/${locationId}/customFields?model=contact`);
if (!fieldsRes.ok) {
  throw new Error(`Failed to fetch custom fields: ${fieldsRes.status} ${JSON.stringify(fieldsRes.data)}`);
}

const existingFields = getCustomFieldsArray(fieldsRes.data);
const fieldByName = new Map();
for (const field of existingFields) {
  const name = extractFieldName(field);
  if (name) fieldByName.set(name, field);
}

const conflicts = [];
const report = [];
const toCreate = [];

for (const req of requiredFields) {
  const existing = fieldByName.get(req.name);
  if (!existing) {
    toCreate.push(req);
    continue;
  }

  const existingType = extractFieldType(existing);
  if (existingType !== req.requiredType) {
    conflicts.push({
      fieldName: req.name,
      existingType: existing?.dataType || existing?.fieldType || existing?.type || 'UNKNOWN',
      requiredType: req.requiredType,
    });
  } else {
    report.push({
      fieldName: req.name,
      fieldId: existing.id || existing._id || 'N/A',
      type: req.requiredType,
      action: 'Reused',
    });
  }
}

if (conflicts.length > 0) {
  const lines = conflicts.map((c) => `${c.fieldName} | ${c.existingType} | ${c.requiredType}`);
  throw new Error(`CONFLICT:\n${lines.join('\n')}`);
}

async function createField(req) {
  const candidates = [];

  if (req.requiredType === 'TEXT') {
    for (const dataType of ['TEXT', 'LARGE_TEXT', 'STRING']) {
      candidates.push({ name: req.name, model: 'contact', dataType });
      candidates.push({ name: req.name, objectKey: 'contact', dataType });
    }
  }

  if (req.requiredType === 'NUMBER') {
    for (const dataType of ['NUMERICAL', 'NUMBER', 'INTEGER']) {
      candidates.push({ name: req.name, model: 'contact', dataType });
      candidates.push({ name: req.name, objectKey: 'contact', dataType });
    }
  }

  if (req.requiredType === 'DATE') {
    for (const dataType of ['DATE', 'DATETIME', 'DATE_TIME']) {
      candidates.push({ name: req.name, model: 'contact', dataType });
      candidates.push({ name: req.name, objectKey: 'contact', dataType });
    }
  }

  let lastError = null;
  for (const body of candidates) {
    const res = await apiRequest.call(this, 'POST', `/locations/${locationId}/customFields`, body);
    if (res.ok) return res.data;
    lastError = { status: res.status, data: res.data, body };
  }

  throw new Error(`Failed creating field ${req.name}: ${JSON.stringify(lastError)}`);
}

if (!dryRun) {
  for (const req of toCreate) {
    const created = await createField.call(this, req);
    report.push({
      fieldName: req.name,
      fieldId: created?.id || created?.data?.id || created?.customField?.id || 'N/A',
      type: req.requiredType,
      action: 'Created',
    });
  }
} else {
  for (const req of toCreate) {
    report.push({
      fieldName: req.name,
      fieldId: 'N/A',
      type: req.requiredType,
      action: 'Planned Create (dryRun)',
    });
  }
}

report.sort((a, b) => a.fieldName.localeCompare(b.fieldName));

return [{
  json: {
    dryRun,
    locationId,
    CUSTOM_FIELDS: report,
  },
}];
